"""Informe HTML offline complementario. No utiliza ni valida DAX."""
from pathlib import Path
import csv,json
R=Path(__file__).resolve().parents[1]
def load(n):return list(csv.DictReader((R/'01_datos/star'/f'{n}.csv').open(encoding='utf-8')))
products={int(r['ProductoID']):r for r in load('DimProducto')};stores={int(r['TiendaID']):r for r in load('DimTienda')};clients={int(r['ClienteID']):r for r in load('DimCliente')}
# Compact arrays reduce file size; integer cents stay exact in JavaScript at this scale.
rows=[[r['Fecha'],int(r['PedidoID']),int(r['ClienteID']),int(r['ProductoID']),int(r['TiendaID']),int(r['Cantidad']),int(r['VentaNetaCent']),int(r['CostoTotalCent']),int(r['DescuentoCent']),int(r['VentaBrutaCent'])] for r in load('FactVentas')]
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Andes Comercial · Informe interactivo</title>
<style>
:root{--navy:#16324f;--teal:#087f8c;--muted:#64748b;--bg:#f2f5f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px 'Segoe UI',Arial,sans-serif;color:var(--navy)}header{background:var(--navy);color:white;padding:28px 4% 22px}header small{color:#8de0d7;letter-spacing:3px}h1{font-size:30px;margin:10px 0}header p{color:#cbd5e1;margin:6px 0}.notice{padding:12px 4%;background:#fff3d9;color:#624912;font-size:13px}.toolbar{display:flex;gap:16px;align-items:end;flex-wrap:wrap;padding:20px 4%;background:white;border-bottom:1px solid #dae2ec}label{display:grid;gap:6px;color:var(--muted);font-size:12px;font-weight:600}select,button{padding:10px 16px;border:1px solid #cbd5e1;border-radius:7px;background:white;color:var(--navy);font-size:14px;cursor:pointer}nav{display:flex;gap:8px;flex-wrap:wrap;padding:18px 4% 0}nav button{border:0;background:transparent}nav button.active{background:var(--teal);color:white}main{padding:18px 4% 36px;max-width:1600px;margin:auto}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}.kpi,.panel{background:white;border-radius:12px;padding:22px;box-shadow:0 2px 6px #102a4310}.kpi small{color:var(--muted);font-size:12px}.kpi strong{display:block;font-size:26px;margin-top:12px;letter-spacing:-.5px}.grid{display:grid;grid-template-columns:1.25fr 1fr;gap:20px;margin-top:20px}.panel h2{font-size:17px;margin:0 0 16px}.sub{font-size:12px;color:var(--muted);margin:5px 0 16px}.barrow{display:grid;grid-template-columns:135px 1fr 115px;align-items:center;gap:12px;font-size:12px;margin:12px 0}.bar{height:15px;background:var(--teal);border-radius:3px}.track{background:#eef3f7;border-radius:3px}.barrow b{text-align:right}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;background:#f4f7fa;padding:11px 8px;color:#64748b}td{padding:10px 8px;border-bottom:1px solid #edf1f5}td.num{text-align:right;font-variant-numeric:tabular-nums}.scroll{overflow:auto;max-height:390px}footer{font-size:12px;color:var(--muted);padding:0 4% 25px}svg{width:100%;height:auto}h2.page{margin:0 0 18px;font-size:20px}.empty{padding:70px;color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.kpi strong{font-size:22px}}
</style>
<header><small>ANDES COMERCIAL</small><h1>Ventas, rentabilidad y clientes</h1><p>2023—2025 · Empresa ficticia peruana · PEN sin IGV</p></header>
<div class="notice">Informe HTML complementario con cálculos JavaScript. No es Power BI y no demuestra ejecución de DAX. El proyecto PBIP requiere validación en Desktop.</div>
<div class="toolbar"><label>AÑO<select id="year"><option value="">Todos los años</option><option>2023</option><option>2024</option><option>2025</option></select></label><label>REGIÓN DE TIENDA<select id="region"></select></label><label>CATEGORÍA<select id="category"></select></label><button id="reset">Limpiar filtros</button><span id="scope" class="sub"></span></div>
<nav id="nav"></nav><main id="app"></main><footer>RFM fijo al 31/12/2025. Datos sintéticos y cálculos locales, sin solicitudes de red. Gráficos de barras muestran valores exactos en etiquetas o tooltip.</footer>
<script>
const ROWS=__ROWS__, PRODUCTS=__PRODUCTS__, STORES=__STORES__, CLIENTS=__CLIENTS__;
const names=['Resumen ejecutivo','Productos y rentabilidad','Clientes','Geografía y tiempo'];let active=0;
const el=id=>document.getElementById(id),num=n=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:0}).format(n),sol=n=>'S/ '+new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100),pct=n=>n===null?'—':(100*n).toFixed(2)+' %';
const options=(id,values,caption)=>{el(id).innerHTML='<option value="">'+caption+'</option>'+values.map(v=>'<option>'+v+'</option>').join('')};
options('region',[...new Set(Object.values(STORES).map(t=>t.Region))].sort(),'Todas las regiones');options('category',[...new Set(Object.values(PRODUCTS).map(p=>p.Categoria))].sort(),'Todas las categorías');
function summary(rs){let v=0,c=0,d=0,g=0,q=0,orders=new Set(),clients=new Set();for(const r of rs){v+=r[6];c+=r[7];d+=r[8];g+=r[9];q+=r[5];orders.add(r[1]);clients.add(r[2])}return {v,c,d,g,q,orders:orders.size,clients:clients.size,margin:v?(v-c)/v:null,ticket:orders.size?v/orders.size:0,freq:clients.size?orders.size/clients.size:0}}
function filtered(y=el('year').value){return ROWS.filter(r=>(!y||r[0].startsWith(y))&&(!el('region').value||STORES[r[4]].Region===el('region').value)&&(!el('category').value||PRODUCTS[r[3]].Categoria===el('category').value))}
function group(rs,fn){const map=new Map();for(const r of rs){const k=fn(r);if(!map.has(k))map.set(k,[]);map.get(k).push(r)}return [...map].map(([name,rows])=>({name,...summary(rows)}))}
const panel=(title,body,sub='')=>'<section class="panel"><h2>'+title+'</h2><p class="sub">'+sub+'</p>'+body+'</section>';
function bars(data,field='v',formatter=sol){let max=Math.max(1,...data.map(x=>x[field]));return data.map(x=>'<div class="barrow"><span>'+x.name+'</span><div class="track"><div class="bar" style="width:'+100*x[field]/max+'%"></div></div><b>'+formatter(x[field])+'</b></div>').join('')}
function table(headers,rows){return '<div class="scroll"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((c,i)=>'<td class="'+(i?'num':'')+'">'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function line(data){let max=Math.max(1,...data.map(x=>x.v)),w=760,h=245,pad=42;let pts=data.map((d,i)=>[pad+i*(w-pad*2)/Math.max(1,data.length-1),h-pad-(h-pad*2)*d.v/max]);return '<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Ventas mensuales"><line x1="42" y1="203" x2="718" y2="203" stroke="#cad5df"/><polyline fill="none" stroke="#087f8c" stroke-width="3" points="'+pts.map(p=>p.join(',')).join(' ')+'"/>'+pts.map((p,i)=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="#087f8c"><title>'+data[i].name+': '+sol(data[i].v)+'</title></circle>'+((i%Math.max(1,Math.floor(data.length/6))===0)?'<text x="'+p[0]+'" y="230" text-anchor="middle" font-size="11" fill="#64748b">'+data[i].name+'</text>':'')).join('')+'<text x="42" y="18" font-size="12" fill="#64748b">Máximo: '+sol(max)+'</text></svg>'}
function kpis(items){return '<div class="kpis">'+items.map(([l,v])=>'<div class="kpi"><small>'+l+'</small><strong>'+v+'</strong></div>').join('')+'</div>'}
function render(){let rs=filtered(),s=summary(rs);window.currentSummary=s;el('scope').textContent=num(rs.length)+' líneas visibles';el('nav').innerHTML=names.map((n,i)=>'<button data-page="'+i+'" class="'+(active===i?'active':'')+'">0'+(i+1)+' '+n+'</button>').join('');el('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{active=+b.dataset.page;render()});let head='<h2 class="page">'+names[active]+'</h2>';let month=group(rs,r=>r[0].slice(0,7)).sort((a,b)=>a.name.localeCompare(b.name));let body='';
if(active===0){body=kpis([['Ventas netas',sol(s.v)],['Utilidad bruta',sol(s.v-s.c)],['Margen bruto',pct(s.margin)],['Pedidos',num(s.orders)],['Ticket promedio',sol(s.ticket)]]);let annual=group(filtered(''),r=>r[0].slice(0,4)).sort((a,b)=>a.name.localeCompare(b.name));body+='<div class="grid">'+panel('Evolución mensual',line(month),'Importes sin IGV. Pase el cursor por los puntos.')+panel('Comparación anual',bars(annual),'Mantiene región y categoría; muestra los tres años para comparar.')+panel('Control de rentabilidad',table(['Año','Ventas','Costo','Margen'],annual.map(x=>[x.name,sol(x.v),sol(x.c),pct(x.margin)])))+panel('Composición por categoría',bars(group(rs,r=>PRODUCTS[r[3]].Categoria).sort((a,b)=>b.v-a.v)))+'</div>'}
if(active===1){let prods=group(rs,r=>PRODUCTS[r[3]].Producto).sort((a,b)=>b.v-a.v),cats=group(rs,r=>PRODUCTS[r[3]].Categoria).sort((a,b)=>b.v-a.v);body=kpis([['Ventas netas',sol(s.v)],['Utilidad bruta',sol(s.v-s.c)],['Descuentos',sol(s.d)],['Descuento efectivo',pct(s.g?s.d/s.g:null)],['Unidades',num(s.q)]]);body+='<div class="grid">'+panel('10 productos con más ventas',table(['Producto','Ventas','Participación'],prods.slice(0,10).map(x=>[x.name,sol(x.v),pct(s.v?x.v/s.v:null)])),'Porcentaje sobre toda la selección, no solo el top 10.')+panel('Ventas por categoría',bars(cats))+panel('10 productos de menor margen',table(['Producto','Utilidad','Margen'],[...prods].sort((a,b)=>a.margin-b.margin).slice(0,10).map(x=>[x.name,sol(x.v-x.c),pct(x.margin)])))+panel('Descuentos y rentabilidad',table(['Categoría','Descuento','Margen'],cats.map(x=>[x.name,pct(x.g?x.d/x.g:null),pct(x.margin)])))+'</div>'}
if(active===2){let customers=group(rs,r=>String(r[2])).sort((a,b)=>b.v-a.v),segments={};Object.values(CLIENTS).forEach(c=>segments[c.SegmentoRFM]=(segments[c.SegmentoRFM]||0)+1);body=kpis([['Compradores',num(s.clients)],['Frecuencia',s.freq.toFixed(2)],['Ticket promedio',sol(s.ticket)],['Maestro completo','2 000'],['Corte RFM','31/12/2025']]);body+='<div class="grid">'+panel('Segmentación RFM del maestro',bars(Object.entries(segments).map(([name,v])=>({name,v})).sort((a,b)=>b.v-a.v),'v',num),'Snapshot histórico fijo: no responde a los filtros.')+panel('Clientes de mayor valor',table(['Cliente','Ventas visibles','Segmento fijo'],customers.slice(0,10).map(x=>[CLIENTS[x.name].Cliente,sol(x.v),CLIENTS[x.name].SegmentoRFM])))+panel('Compradores por mes',bars(month.map(x=>({name:x.name,v:x.clients})),'v',num),'Conteos mensuales no aditivos.')+panel('Frecuencia por mes',table(['Mes','Pedidos','Clientes','Frecuencia'],month.map(x=>[x.name,num(x.orders),num(x.clients),x.freq.toFixed(2)])))+'</div>'}
if(active===3){let reg=group(rs,r=>STORES[r[4]].Region).sort((a,b)=>b.v-a.v),zones=group(rs,r=>STORES[r[4]].Zona).sort((a,b)=>b.v-a.v),all=filtered('');let mm=new Map(group(all,r=>r[0].slice(0,7)).map(x=>[x.name,x.v]));body=kpis([['Ventas netas',sol(s.v)],['Regiones visibles',String(reg.length)],['Pedidos',num(s.orders)],['Utilidad',sol(s.v-s.c)],['Margen',pct(s.margin)]]);body+='<div class="grid">'+panel('Ventas por región de tienda',bars(reg),'Ubicación de la venta, no domicilio del cliente.')+panel('Comparación entre zonas',table(['Zona','Ventas','Margen'],zones.map(x=>[x.name,sol(x.v),pct(x.margin)])))+panel('Evolución temporal',line(month))+panel('Crecimiento interanual',table(['Mes','Ventas','Año previo','YoY'],month.map(x=>{let prev=mm.get((+x.name.slice(0,4)-1)+x.name.slice(4));return [x.name,sol(x.v),prev?sol(prev):'—',prev?pct((x.v-prev)/prev):'—']})),'Sin comparativo 2022: se muestra —.')+'</div>'}
el('app').innerHTML=head+(rs.length?body:'<div class="empty">Sin ventas para esta selección.</div>')}
['year','region','category'].forEach(id=>el(id).onchange=render);el('reset').onclick=()=>{['year','region','category'].forEach(id=>el(id).value='');render()};render();
</script></html>'''
for k,v in [('ROWS',rows),('PRODUCTS',products),('STORES',stores),('CLIENTS',clients)]:html=html.replace('__'+k+'__',json.dumps(v,ensure_ascii=False,separators=(',',':')))
(R/'04_powerbi/informe_interactivo.html').write_text(html,encoding='utf-8')
print('HTML offline generado')
